test_cases.assertion_pseudocode:
// Go test
result := spec.RenderIndividualScoped(1)
assert result != nil
assert len(result) > 0
// Verify scoped (only inferred req present)
assert strings.Contains(result["requirements"], inferredReqId)
// No log assertions needed — Go has no logging infrastructure

property_tests.invariant_check:
result = render_individual_scoped(spec, target_group)
tasks_output = result['tasks']
# Only target group tasks present
for group in spec.tasks.task_groups:
    if group.id == target_group:
        assert any(subtask.id in tasks_output for subtask in group.subtasks)
    else:
        assert all(subtask.id not in tasks_output for subtask in group.subtasks)

edge_case_tests.assertion_pseudocode:
result := spec.RenderIndividualScoped(1)
// Tasks scoped — group 2 tasks absent
assert !strings.Contains(result["tasks"], group2TaskMarker)
// Group 1 tasks present
assert strings.Contains(result["tasks"], group1TaskMarker)
// Full requirements still present (fallback)
assert len(result["requirements"]) > 0
